const day=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lang=()=>{const v=$('#adminLanguage')?.value||localStorage.getItem('panora-admin-lang')||'ru';return ['ru','en','es'].includes(v)?v:'ru'};
const tr=(ru,en,es)=>lang()==='en'?en:lang()==='es'?es:ru;
const locale=()=>lang()==='en'?'en-GB':lang()==='es'?'es-ES':'ru-RU';
const fmt=d=>{if(!d)return'—';try{return new Intl.DateTimeFormat(locale(),{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${String(d).slice(0,10)}T12:00:00`))}catch{return String(d)}};
const fmtTime=d=>{if(!d)return'—';try{return new Intl.DateTimeFormat(locale(),{dateStyle:'short',timeStyle:'short'}).format(new Date(d))}catch{return String(d)}};
const num=v=>Number.isFinite(Number(v))?Number(v):0;
const ps=()=>window.panoraProductionSafety?.read?.()||{};
const mutate=fn=>window.panoraProductionSafety?.mutate?.(fn);
const products=()=>{try{return (window.panoraProductRegistry?.()||window.productRegistry||JSON.parse(localStorage.getItem('panora-products')||'[]')||[]).filter(Boolean)}catch{return[]}};
const productName=id=>{const p=products().find(x=>String(x.id)===String(id)),n=p?.names||{};return lang()==='en'?(n.en||n.ru||id):lang()==='es'?(n.es||n.ru||id):(n.ru||n.en||id||'—')};
const restaurants=()=>{try{return JSON.parse(localStorage.getItem('panora-restaurants')||'[]')||[]}catch{return[]}};
const restaurantName=id=>restaurants().find(r=>String(r.id)===String(id))?.name||'—';
