const noteName=id=>{const n=notes().find(x=>String(x.id)===String(id));return n?`DN-${String(n.number||n.noteNumber||n.id).padStart?.(4,'0')||n.id}`:'—'};
const statusLabel=s=>({open:tr('Открыто','Open','Abierto'),fixing:tr('В работе','In progress','En curso'),closed:tr('Закрыто','Closed','Cerrado'),pass:tr('Соответствует','Pass','Conforme'),attention:tr('Требует внимания','Attention','Atención'),fail:tr('Не соответствует','Fail','No conforme'),draft:tr('Черновик','Draft','Borrador'),approved:tr('Утверждено','Approved','Aprobado'),superseded:tr('Заменено','Superseded','Sustituido'),active:tr('Активно','Active','Activo'),blocked:tr('Заблокировано','Blocked','Bloqueado')}[s]||s||'—');
const statusClass=s=>['closed','pass','approved','active'].includes(s)?'active':['fail','blocked'].includes(s)?'blocked':'using';
let partnerCases=[],partnerCasesLoaded=0,partnerCasesLoading=null;

async function api(path,options={}){
 const session=window.panoraSupabaseSession;if(!cfg.url||!cfg.publishableKey||!session?.access_token)throw new Error('NO_SESSION');
 const res=await fetch(`${cfg.url}/rest/v1/${path}`,{cache:'no-store',...options,headers:{apikey:cfg.publishableKey,Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json','Cache-Control':'no-cache',...(options.headers||{})}});
 const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}
 if(!res.ok){const e=new Error(data?.message||data?.hint||String(data||`HTTP ${res.status}`));e.status=res.status;throw e}return data;
}
async function loadPartnerCases(force=false){
 if(partnerCasesLoading)return partnerCasesLoading;if(!navigator.onLine||!window.panoraSupabaseSession?.access_token)return partnerCases;
 if(!force&&Date.now()-partnerCasesLoaded<15000)return partnerCases;
 partnerCasesLoading=(async()=>{try{const rows=await api('partner_quality_cases?select=id,restaurant_id,delivery_note_id,order_id,product_id,lot_number,case_type,description,requested_action,status,bakery_response,responsible,created_at,updated_at&order=created_at.desc');partnerCases=Array.isArray(rows)?rows:[];partnerCasesLoaded=Date.now();return partnerCases}catch(e){if(!/partner_quality_cases|PGRST|404|relation/i.test(String(e?.message||'')))console.warn('Panora quality cases',e);return partnerCases}finally{partnerCasesLoading=null}})();return partnerCasesLoading;
}
async function patchPartnerCase(id,patch){await api(`partner_quality_cases?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({...patch,updated_at:now()}),headers:{Prefer:'return=minimal'}});partnerCasesLoaded=0;await loadPartnerCases(true);renderQuality()}

